[
  {
    "sys_consequence_reasoning": "Five people against a dented barrier and a stalled train isn't close",
    "pda_responsibility": "I'm the one who grabbed railway equipment",
    "pda_repair_intention": "offer to cover repairs",
    "sys_instrumental_norm_use": "I only keep my hands off levers like that because it spares me fines",
    "pd_personal_consequence_anxiety": "spares me fines and hassle"
  },
  {
    "pd_decision_conflict": "My stomach drops just picturing it",
    "pda_responsibility": "that happened because I chose to act",
    "pda_repair_intention": "wait for staff, and write down the time, what I saw, and why",
    "sys_instrumental_norm_use": "I go along with it when it keeps me out of trouble"
  },
  {
    "ce_mental_state_attribution": "I'm assuming the lever really does send the train into the siding",
    "pd_decision_conflict": "it scares me a bit",
    "pda_responsibility": "it went wrong through my hand, nobody else's",
    "pda_repair_intention": "report myself to the railway, explain everything, and pay",
    "sys_instrumental_norm_use": "I follow them because breaking them usually costs me"
  },
  {
    "ce_mentalizing_difficulty": "I don't know if they'd hear over the noise",
    "sys_consequence_reasoning": "Some damage and disruption against five lives",
    "pda_responsibility": "The damage is mine, though. I made that call",
    "pda_repair_intention": "own up, and ask how to put right whatever I messed up",
    "sys_instrumental_norm_use": "stay off the tracks and away from equipment because getting caught is expensive"
  },
  {
    "sys_consequence_reasoning": "No one's in danger from the switch, and five people are in danger without",
    "pd_decision_conflict": "The part that makes me tense is afterward",
    "pda_responsibility": "Tampering is tampering, and I chose to do it",
    "pda_repair_intention": "offer to pay for the barrier or any delays",
    "sys_instrumental_norm_use": "keep to the rules around trains mostly because it's cheaper than not"
  },
  {
    "pd_decision_conflict": "Heart pounding, but yes",
    "pd_personal_consequence_anxiety": "What worries me isn't the choice, it's the mess",
    "pda_responsibility": "I'm the person who caused it",
    "pda_repair_intention": "wait on the platform, explain to the staff what happened, and sign whatever",
    "sys_instrumental_norm_use": "I respect that only as long as it protects me"
  },
  {
    "pd_decision_conflict": "It feels awful to be the only one there",
    "pda_responsibility": "And if pulling it damages the siding, I caused that too",
    "pda_repair_intention": "contact the railway afterward, tell them plainly it was me",
    "sys_instrumental_norm_use": "I don't touch railway gear normally because I don't want the penalties"
  },
  {
    "sys_consequence_reasoning": "The workers matter more than a barrier or a timetable",
    "pda_responsibility": "my hand moved that lever... I own that",
    "pda_repair_intention": "explain why I did it, and offer to cover costs",
    "sys_instrumental_norm_use": "follow the rules at stations to keep myself out of trouble"
  },
  {
    "pd_decision_conflict": "my hands feel cold thinking about it",
    "pd_personal_consequence_anxiety": "maybe my own neck legally",
    "pda_responsibility": "I'm the one who decides to take that risk",
    "pda_repair_intention": "go to the office, give them the full story, and pay for anything broken",
    "sys_instrumental_norm_use": "honestly only obey the no-touching rule because breaking it normally gets you fined"
  },
  {
    "pd_decision_conflict": "I'd be sick with nerves",
    "ce_mentalizing_difficulty": "I'm not totally sure what hitting that barrier does",
    "pda_responsibility": "outcome traces back to me pulling the lever",
    "pda_repair_intention": "flag down staff, explain, and offer to make good",
    "sys_instrumental_norm_use": "play by the railway's rules when it keeps me safe from fines"
  }
]
